    row_1 = global_maxr + 3
    if row_1 < R:
        for c in range(global_minc - 3, global_maxc + 4):
            if 0 <= c < C:
                out[row_1][c] = 1
    # Also fill rows below with 1s in pattern
    for r in range(row_1 + 1, R):
        for c in range(global_minc - 2, global_maxc + 3):
            if 0 <= c < C and out[r][c] == 1:
